import raw from '@data/curriculum_kntt.json';
import { z } from 'zod';
import { datasetSchema, ReviewStatusSchema } from '@/core/data/dataset';
import type { Subject } from '@/app/workspaceStore';

/**
 * Where each topic sits in the textbooks "Kết nối tri thức với cuộc sống" (grades 10–12):
 * generated by `scripts/data/gen_curriculum_kntt.py` from the official tables of contents
 * (lesson and chapter titles verbatim). User decision 2026-10-22 (plan #37 §3.3): the library
 * may group topics by grade from this data, always labelled as waiting for a teacher's review
 * (DATA_REVIEW 12, KNTT-*). A topic whose lesson is not clearly named is left unplaced.
 */

const SubjectSchema = z.enum(['physics', 'chemistry', 'biology']);
const GradeSchema = z.union([z.literal(10), z.literal(11), z.literal(12)]);
export type Grade = z.infer<typeof GradeSchema>;
export const GRADES: readonly Grade[] = [10, 11, 12];

const LessonSchema = z.object({
  /** null: an unnumbered course lesson (e.g. "Mở đầu"). */
  number: z.number().int().positive().nullable(),
  title: z.string().min(1),
  page: z.number().int().positive(),
  kind: z.enum(['theory', 'intro', 'practice', 'review', 'exercise', 'project', 'career']),
});

const ChapterSchema = z.object({
  /** Chapter title in normal case (the table of contents prints it in capitals). */
  label: z.string().min(1),
  printed: z.string().min(1),
  part: z.string().optional(),
  lessons: z.array(LessonSchema).min(1),
});

const BookSchema = z.object({
  id: z.string().min(1),
  subject: SubjectSchema,
  grade: GradeSchema,
  title: z.string().min(1),
  url: z.url(),
  tocPages: z.array(z.number().int().positive()).min(1),
  chapters: z.array(ChapterSchema).min(1),
  counts: z.object({ total: z.number().int().positive(), theory: z.number().int().positive() }),
});

const PlacementSchema = z.object({
  topic: z.string().min(1),
  subject: SubjectSchema,
  grade: GradeSchema,
  book: z.string().min(1),
  chapter: z.string().min(1),
  lessons: z.array(z.number().int().positive()).min(1),
  reason: z.string().min(1),
  review_status: ReviewStatusSchema,
});

const UnplacedSchema = z.object({
  topic: z.string().min(1),
  subject: SubjectSchema,
  reason: z.string().min(1),
  review_status: ReviewStatusSchema,
});

const CurriculumSchema = datasetSchema(PlacementSchema).extend({
  review_status: ReviewStatusSchema,
  accessed: z.iso.date(),
  books: z.array(BookSchema).min(1),
  unplaced: z.array(UnplacedSchema),
});
export type Curriculum = z.infer<typeof CurriculumSchema>;

function load(data: unknown): Curriculum {
  const result = CurriculumSchema.safeParse(data);
  if (!result.success)
    throw new Error(`Invalid dataset "curriculum_kntt": ${z.prettifyError(result.error)}`);
  return result.data;
}

export const CURRICULUM: Curriculum = load(raw);

export interface GradeTopic {
  topic: string;
  lessons: readonly number[];
}

export interface GradeChapter {
  /** Chapter title as in the textbook (normal case). */
  label: string;
  topics: GradeTopic[];
}

/**
 * A grade's chapters with their placed topics, in the book's order (topics by their first
 * lesson). A topic placed in two grades appears in both; a grade without topics gives [].
 */
export function gradeView(grade: Grade, subject: Subject, data = CURRICULUM): GradeChapter[] {
  const out: GradeChapter[] = [];
  for (const book of data.books.filter((b) => b.grade === grade && b.subject === subject)) {
    for (const chapter of book.chapters) {
      const topics = data.items
        .filter((p) => p.book === book.id && p.chapter === chapter.label)
        .map((p) => ({ topic: p.topic, lessons: p.lessons }))
        .sort((a, b) => (a.lessons[0] ?? 0) - (b.lessons[0] ?? 0));
      if (topics.length > 0) out.push({ label: chapter.label, topics });
    }
  }
  return out;
}

/** "31–32", "4–5, 7", "14–16, 18": consecutive lessons as a range (en dash). */
export function lessonRange(numbers: readonly number[]): string {
  const sorted = [...new Set(numbers)].sort((a, b) => a - b);
  const parts: string[] = [];
  for (let i = 0; i < sorted.length;) {
    let j = i;
    while (j + 1 < sorted.length && sorted[j + 1] === (sorted[j] ?? 0) + 1) j++;
    parts.push(i === j ? `${sorted[i]}` : `${sorted[i]}–${sorted[j]}`);
    i = j + 1;
  }
  return parts.join(', ');
}
